import{_ as n,o as a,c as t,a3 as i}from"./chunks/framework.MGD2uYU7.js";const r=JSON.parse('{"title":"SC-07 — Bảng gói VIP","description":"","frontmatter":{"title":"SC-07 — Bảng gói VIP"},"headers":[],"relativePath":"wireframes/public/sc-07-bang-goi.md","filePath":"wireframes/public/sc-07-bang-goi.md","lastUpdated":1791606799000}'),l={name:"wireframes/public/sc-07-bang-goi.md"};function c(d,s,o,p,e,g){return a(),t("div",null,[...s[0]||(s[0]=[i('<h1 id="sc-07-—-bang-goi-vip" tabindex="-1">SC-07 — Bảng gói VIP <a class="header-anchor" href="#sc-07-—-bang-goi-vip" aria-label="Permalink to &quot;SC-07 — Bảng gói VIP&quot;">​</a></h1><p><span class="wf-badge muted">ĐỘ PHỨC TẠP: THẤP</span> <span class="wf-badge info">Route: /bang-goi</span> <span class="wf-badge muted">Nguồn: docs/05 §3 SC-07 · docs/03 UC-10 · docs/06 §4.9 · docs/08 BR-PKG</span></p><p><strong>Ai xem màn này</strong>: Chủ nhà đang/ sắp đăng tin (quyết định mua gói), Guest tò mò về mô hình kinh doanh của sàn. <strong>Mục đích / cảm xúc thiết kế</strong>: bảng giá <strong>tĩnh lặng, trung thực</strong> — đúng tinh thần &quot;không màu sale lòe&quot; (docs/05 §1.1): số liệu quyền lợi rõ từng dòng, không countdown giả, không &quot;chỉ còn 2 suất&quot;. Giá chờ OQ-8 duyệt — cấu trúc card không đổi khi số đổi. <strong>Ví dụ số dùng trong bản vẽ</strong> (docs/06 §4.9 — seed packages): <code>FREE</code> 0 ₫ / 2 tin · <code>VIP_STANDARD</code> 500.000 ₫ / 30 ngày / 10 tin · <code>VIP_PRO</code> 1.500.000 ₫ / 30 ngày / 50 tin · quyền lợi: listingLimit, featuredBadge (★), prioritySort.</p><h2 id="_1-desktop-—-3-pricing-card-bang-so-sanh" tabindex="-1">1. Desktop — 3 pricing card + bảng so sánh <a class="header-anchor" href="#_1-desktop-—-3-pricing-card-bang-so-sanh" aria-label="Permalink to &quot;1. Desktop — 3 pricing card + bảng so sánh&quot;">​</a></h2><div class="wf"><div class="wf-screen"><div class="wf-browser-bar"><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-url">anphuc.vn/bang-goi</span></div><div class="wf-body"><div class="wf-header"><span class="wf-logo">AnPhuc</span><span class="wf-nav"><span>Mua nhà</span><span>Đấu giá</span><span class="active">Bảng gói</span><span>Hướng dẫn</span></span><span class="wf-header-actions"><span class="wf-bell">🔔<span class="count">2</span></span><span class="wf-avatar">NA</span></span></div><div class="wf-container"><div class="wf-center" style="margin-bottom:18px;"><span class="wf-title xl">Gói đăng tin cho chủ nhà <span class="wf-callout">1</span></span><br><span class="wf-text">Mua nhà luôn miễn phí — gói chỉ dành cho người đăng bán. Thanh toán 1 lần cho 30 ngày, không tự gia hạn.</span></div><div class="wf-grid cols-3"><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><span class="wf-title lg">Miễn phí</span><span class="wf-money lg">0 ₫</span><span class="wf-small">Mặc định cho mọi tài khoản</span><div class="wf-lines"><span class="w-100"></span><span class="w-90"></span><span class="w-75"></span></div><table class="wf-table"><tbody><tr><td>Số tin đồng thời</td><td><b>2</b></td></tr><tr><td>Badge ★ VIP trên tin</td><td>—</td></tr><tr><td>Ưu tiên sort &quot;Nổi bật&quot;</td><td>—</td></tr></tbody></table><span class="wf-btn disabled block">Gói hiện tại <span class="wf-callout">4</span></span></div></div><div class="wf-card" style="border:2px solid var(--wf-accent);"><div class="pad wf-col" style="gap:8px;"><span class="wf-row between middle"><span class="wf-title lg">VIP Standard</span><span class="wf-badge info">PHỔ BIẾN <span class="wf-callout">2</span></span></span><span class="wf-money lg">500.000 ₫ <span class="wf-small" style="font-weight:400;">/ 30 ngày</span></span><span class="wf-small">Cho chủ nhà bán 1–2 căn nhưng muốn tin được thấy trước</span><div class="wf-lines"><span class="w-100"></span><span class="w-75"></span></div><table class="wf-table"><tbody><tr><td>Số tin đồng thời</td><td><b>10</b></td></tr><tr><td>Badge ★ VIP trên tin</td><td><b class="wf-ok-text">✓</b></td></tr><tr><td>Ưu tiên sort &quot;Nổi bật&quot;</td><td><b class="wf-ok-text">✓</b></td></tr></tbody></table><span class="wf-btn primary block">Mua gói <span class="wf-callout">3</span></span><span class="wf-small wf-center">Thanh toán VNPay hoặc chuyển khoản · kích hoạt ngay khi tiền về</span></div></div><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><span class="wf-title lg">VIP Pro</span><span class="wf-money lg">1.500.000 ₫ <span class="wf-small" style="font-weight:400;">/ 30 ngày</span></span><span class="wf-small">Cho người bán nhiều căn / môi giới hộ người thân</span><div class="wf-lines"><span class="w-100"></span><span class="w-60"></span></div><table class="wf-table"><tbody><tr><td>Số tin đồng thời</td><td><b>50</b></td></tr><tr><td>Badge ★ VIP trên tin</td><td><b class="wf-ok-text">✓</b></td></tr><tr><td>Ưu tiên sort &quot;Nổi bật&quot;</td><td><b class="wf-ok-text">✓</b></td></tr></tbody></table><span class="wf-btn block">Mua gói</span><span class="wf-small wf-center">Rẻ hơn Standard theo mỗi tin nếu dùng trên 30 tin/tháng</span></div></div></div><div class="wf-card flat" style="margin-top:20px;"><div class="pad wf-col" style="gap:8px;"><span class="wf-title">So sánh chi tiết quyền lợi <span class="wf-callout">5</span></span><table class="wf-table"><thead><tr><th>Quyền lợi</th><th>Miễn phí</th><th>VIP Standard</th><th>VIP Pro</th></tr></thead><tbody><tr><td>Số tin đăng đồng thời (`listingLimit`)</td><td>2</td><td>10</td><td>50</td></tr><tr><td>Badge ★ VIP trên tin (`featuredBadge`)</td><td>—</td><td>✓</td><td>✓</td></tr><tr><td>Lên đầu sort &quot;Nổi bật&quot; (`prioritySort`)</td><td>—</td><td>✓</td><td>✓</td></tr><tr><td>Thời hạn</td><td>Không hết hạn</td><td>30 ngày</td><td>30 ngày</td></tr><tr><td>Giá</td><td>0 ₫</td><td><b class="wf-money">500.000 ₫</b></td><td><b class="wf-money">1.500.000 ₫</b></td></tr></tbody></table><span class="wf-small">Đếm quota: tin đang LISTED/RESERVED + tin SOLD trong 30 ngày gần nhất; hết gói <b>không cắt tin đang sống</b> — chỉ chặn submit tin mới. <span class="wf-callout">6</span></span></div></div><div class="wf-note" style="margin-top:14px;">Giá gói là số liệu cấu hình (chờ ban điều hành duyệt — OQ-8). FE đọc `GET /packages`, <b>không hardcode giá vào layout</b>; đổi giá không đổi thiết kế.</div></div><div class="wf-footer"><span>AnPhucRealEstate — sàn NOXH được vận hành bởi An Phuc</span><span>Quy chế đấu giá</span><span>CSKH 1900-xxx</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích hành vi (trace: docs/05 §3 SC-07 · docs/03 UC-10 · docs/08 BR-PKG)</div><ol><li><span class="num">1</span><span>Nguồn dữ liệu `GET /packages` (🌐 public, endpoint 40 — payload docs/06 §4.9). Guest xem được toàn bộ bảng giá; chỉ nút Mua là phân biệt trạng thái đăng nhập. <span class="ref">FR-PKG-01</span></span></li><li><span class="num">2</span><span>Nhãn &quot;PHỔ BIẾN&quot; gắn cứng vào VIP_STANDARD (quyết định sản phẩm, không A/B test trong v1) — là card duy nhất có viền accent. Không dùng nhãn kiểu &quot;tiết kiệm nhất&quot;/&quot;khuyên dùng gấp&quot;. <span class="ref">docs/05 §1.1</span></span></li><li><span class="num">3</span><span><b>Nút &quot;Mua gói&quot;</b> → `POST /subscriptions/checkout {packageCode}` → redirect VNPay → quay lại resume → poll `/users/me/subscriptions` → banner ACTIVE &quot;VIP đã kích hoạt&quot; + về SC-26. Hủy tại gateway → về SC-07 giữ nguyên context. Gateway down → panel chuyển khoản thủ công (content bill `ANPHUC …`, ADMIN xác nhận ≤2h). <span class="ref">docs/05 §5</span> <span class="ref">UC-10</span> <span class="ref">FR-PAY-03</span></span></li><li><span class="num">4</span><span><b>Trạng thái nút theo người xem</b>: Guest → &quot;Đăng nhập để mua&quot; (deep-link return về /bang-goi); user gói nào → card gói đó disabled &quot;Gói hiện tại&quot;; FREE là gói mặc định nên user chưa mua gì thấy FREE disabled. Đang gửi checkout → nút loading disabled (chống double-submit, Idempotency-Key). <span class="ref">docs/05 §3</span> <span class="ref">docs/06 §1</span></span></li><li><span class="num">5</span><span>Bảng so sánh dùng đúng 3 entitlement trong schema `entitlements {listingLimit, featuredBadge, prioritySort}` — <b>không bịa thêm dòng quyền lợi</b> chưa có trong seed. Sort &quot;Nổi bật&quot; = VIP trước rồi newest, quy tắc tĩnh không AI. <span class="ref">docs/07 §2.13</span> <span class="ref">BR-PKG-06</span></span></li><li><span class="num">6</span><span>Quota enforce lúc submit tin (không phải lúc mua): vượt → 422 message &quot;Bạn đã dùng {used}/{limit} tin. Nâng cấp VIP để đăng thêm&quot; — modal upsell ở SC-22 link về trang này. <span class="ref">BR-PKG-02</span> <span class="ref">docs/06 §5</span></span></li><li><span class="num">7</span><span>Upgrade khi đang ACTIVE gói khác: trước thanh toán hiện <b>modal cảnh báo</b> &quot;Đổi gói: gói cũ kết thúc ngay, không hoàn phần còn lại&quot; (gói cũ → SUPERSEDED). Gia hạn cùng gói → cộng dồn endsAt +30 ngày, không mất gì. <span class="ref">BR-PKG-03</span> <span class="ref">FR-PKG-02</span></span></li></ol></div><h2 id="_2-mobile-360px-—-card-xep-doc-so-sanh-cuon-ngang" tabindex="-1">2. Mobile 360px — card xếp dọc, so sánh cuộn ngang <a class="header-anchor" href="#_2-mobile-360px-—-card-xep-doc-so-sanh-cuon-ngang" aria-label="Permalink to &quot;2. Mobile 360px — card xếp dọc, so sánh cuộn ngang&quot;">​</a></h2><div class="wf"><div class="wf-mobile"><div class="wf-mobile-bar"><span>9:41</span><span>▮▮▮ ⌁ ▰</span></div><div class="wf-header" style="padding:8px 12px;"><span class="wf-logo">AnPhuc</span><span class="wf-bell">🔔<span class="count">2</span></span></div><div class="wf-container" style="padding:12px;"><div class="wf-center"><span class="wf-title lg">Gói đăng tin cho chủ nhà</span><br><span class="wf-small">Mua nhà luôn miễn phí · 30 ngày/gói · không tự gia hạn</span></div><div class="wf-card" style="margin-top:12px;"><div class="pad wf-col" style="gap:4px;"><span class="wf-row between middle"><span class="wf-title">Miễn phí</span><span class="wf-btn disabled sm">Gói hiện tại</span></span><span class="wf-money">0 ₫</span><span class="wf-text">2 tin đồng thời · không badge ★ · không ưu tiên sort</span></div></div><div class="wf-card" style="margin-top:10px;border:2px solid var(--wf-accent);"><div class="pad wf-col" style="gap:4px;"><span class="wf-row between middle"><span class="wf-title">VIP Standard <span class="wf-badge info">PHỔ BIẾN</span></span><span class="wf-money">500.000 ₫</span></span><span class="wf-text">10 tin · badge ★ · lên đầu sort &quot;Nổi bật&quot; · 30 ngày</span><span class="wf-btn primary block">Mua gói</span></div></div><div class="wf-card" style="margin-top:10px;"><div class="pad wf-col" style="gap:4px;"><span class="wf-row between middle"><span class="wf-title">VIP Pro</span><span class="wf-money">1.500.000 ₫</span></span><span class="wf-text">50 tin · badge ★ · lên đầu sort &quot;Nổi bật&quot; · 30 ngày</span><span class="wf-btn block">Mua gói</span></div></div><span class="wf-small" style="display:block;margin-top:10px;">Bảng so sánh chi tiết → table cuộn ngang (sticky cột &quot;Quyền lợi&quot;); FAQ ở dưới cùng như desktop.</span></div><div class="wf-footer"><span>AnPhucRealEstate — vận hành bởi An Phuc</span><span>CSKH 1900-xxx</span></div></div></div><div class="wf-legend"><div class="t">Chú thích mobile</div><ol><li><span class="num">M</span><span>Card gói thu thành 1 dòng tiêu đề + 1 dòng quyền lợi + nút — vẫn giữ <b>đủ 3 con số</b> (giá / limit tin / 30 ngày). Card PHỔ BIẾN giữ viền accent nhưng không đổi thứ tự (Free → Standard → Pro nhất quán desktop). Nút Mua sticky bottom: không dùng (tránh che FAQ).</span></li></ol></div><h2 id="_3-faq-modal-canh-bao-đoi-goi" tabindex="-1">3. FAQ + modal cảnh báo đổi gói <a class="header-anchor" href="#_3-faq-modal-canh-bao-đoi-goi" aria-label="Permalink to &quot;3. FAQ + modal cảnh báo đổi gói&quot;">​</a></h2><div class="wf"><div class="wf-grid"><div class="wf-col"><span class="wf-state-label">KHỐI FAQ (cuối trang, accordion)</span><div class="wf-col" style="gap:8px;"><div class="wf-card flat"><div class="pad wf-row between middle"><span class="wf-title">Mua nhà có phải trả phí không?</span><span class="wf-strong">−</span></div><div class="pad" style="border-top:1px solid var(--wf-line);padding-top:10px;"><span class="wf-text">Không. Toàn bộ tính năng người mua (xem tin, đặt lịch xem, đăng ký đấu giá) miễn phí. Gói VIP chỉ phục vụ người đăng bán.</span></div></div><div class="wf-card flat"><div class="pad wf-row between middle"><span class="wf-title">Hết 30 ngày thì tin của tôi bị hạ?</span><span class="wf-strong">+</span></div></div><div class="wf-card flat"><div class="pad wf-row between middle"><span class="wf-title">Tôi dùng quá 10 tin khi đang ở Standard?</span><span class="wf-strong">+</span></div></div><div class="wf-card flat"><div class="pad wf-row between middle"><span class="wf-title">Có được hoàn tiền nếu hủy giữa chu kỳ?</span><span class="wf-strong">+</span></div></div><div class="wf-card flat"><div class="pad wf-row between middle"><span class="wf-title">Badge ★ VIP nghĩa là tin được sàn đảm bảo?</span><span class="wf-strong">+</span></div></div><div class="wf-note">Nội dung trả lời FAQ: mục 2 = &quot;Không — tin đang sống không bị cắt, chỉ chặn đăng tin mới khi vượt quota FREE (BR-PKG-02/05)&quot;; mục 4 = &quot;v1 không hoàn/hủy giữa chu kỳ (BR-PKG-04)&quot;; mục 5 = &quot;Không — ★ chỉ là quyền lợi hiển thị, mọi tin đều qua duyệt như nhau (BR-HS-07)&quot;. Copy final do Ops viết, PM duyệt.</div></div></div><div class="wf-col"><span class="wf-state-label">MODAL — ĐỔI GÓI KHI ĐANG ACTIVE</span><div class="wf-modal-overlay"><div class="wf-modal"><div class="head">Đổi sang VIP Pro?</div><div class="wf-lines" style="margin:10px 0;"><div class="wf-row between"><span class="wf-text">Gói hiện tại</span><span class="wf-strong">VIP Standard — còn 12 ngày (đến 22/10/2026)</span></div><div class="wf-row between"><span class="wf-text">Sau khi đổi</span><span class="wf-strong">VIP Pro — 30 ngày mới, từ hôm nay</span></div><div class="wf-row between"><span class="wf-text">Phải trả</span><span class="wf-money lg">1.500.000 ₫</span></div></div><div class="wf-note" style="background:var(--wf-warn-soft);border-color:var(--wf-warn);color:var(--wf-warn);"> Gói Standard <b>kết thúc ngay khi đổi</b> — phần 12 ngày còn lại <b>không được hoàn hoặc trừ tiền</b>. <span class="wf-callout warn">7</span></div><div class="wf-row" style="margin-top:12px;"><span class="wf-btn grow" style="flex:1;">Ở lại Standard</span><span class="wf-btn primary grow" style="flex:1;">Vẫn đổi sang Pro</span></div></div></div><span class="wf-small">Gia hạn CÙNG gói không hiện modal này — chỉ confirm thanh toán thường (cộng dồn +30 ngày, không mất gì).</span></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">8</span><span>FAQ dạng accordion (1 câu mở sẵn), nội dung pháp lý/cam kết do Ops + Pháp chế duyệt — designer chỉ dựng khung. Mọi con số trong câu trả lời phải khớp docs/08 (không tự viết số mới). <span class="ref">docs/05 §8</span></span></li><li><span class="num">9</span><span>Modal đổi gói nêu <b>số ngày còn lại thật + số tiền thật</b> — đúng quy tắc &quot;không số gộp, hậu quả cụ thể&quot;. Trạng thái nền của trang: Loading = skeleton 3 card; Error = hộp lỗi + traceId + Thử lại (packages là dữ liệu seed, hiếm lỗi). <span class="ref">BR-PKG-03</span> <span class="ref">docs/05 §1.4</span></span></li></ol></div><h2 id="_4-checklist-designer-khi-dung-figma-cho-sc-07" tabindex="-1">4. Checklist designer khi dựng Figma cho SC-07 <a class="header-anchor" href="#_4-checklist-designer-khi-dung-figma-cho-sc-07" aria-label="Permalink to &quot;4. Checklist designer khi dựng Figma cho SC-07&quot;">​</a></h2><ul><li>[ ] Đủ layout: desktop (3 card ngang + bảng so sánh) / tablet 768 / mobile 360 (card dọc compact)</li><li>[ ] 3 card: FREE (disabled &quot;Gói hiện tại&quot;) · VIP_STANDARD (viền accent + badge PHỔ BIẾN) · VIP_PRO — mỗi card đủ: giá, /30 ngày, listingLimit, ✓/— cho featuredBadge + prioritySort</li><li>[ ] Trạng thái nút đủ 4 biến thể: Guest &quot;Đăng nhập để mua&quot; · chưa mua (FREE disabled) · đang ACTIVE gói khác (modal đổi gói) · loading khi checkout</li><li>[ ] Bảng so sánh 3 cột dùng đúng 3 entitlement schema — không bịa quyền lợi</li><li>[ ] Modal cảnh báo đổi gói: số ngày còn lại + &quot;không hoàn phần còn lại&quot; (BR-PKG-03)</li><li>[ ] FAQ accordion ≥5 câu, khung cho copy Ops/Pháp chế</li><li>[ ] Giá trị lấy từ <code>GET /packages</code> — design không hardcode giá (OQ-8 có thể đổi số)</li><li>[ ] Copy đúng docs/06 §5 (quota message); tiền <code>500.000 ₫</code> / <code>1.500.000 ₫</code>; ngày <code>dd/MM/yyyy HH:mm</code> GMT+7</li><li>[ ] Không emoji icon trong UI production; giọng điệu trung tính — không countdown giả/khan hiếm giả</li><li>[ ] Accessibility: bảng so sánh có scope row/col; card gói là region có aria-label; nút disabled có aria-disabled + giải thích vì sao</li></ul><div class="info custom-block"><p class="custom-block-title">Góp ý màn này?</p><p>Comment ngay bên dưới — ghi rõ khu vực (số callout) và đề xuất. Thay đổi nghiệp vụ (giá gói, quota — OQ-8) cần PM duyệt trên docs/08 trước.</p></div>',15)])])}const u=n(l,[["render",c]]);export{r as __pageData,u as default};
